# ===== DATA TYPES ===== #

# Quality tiers from the moonlit fields #
# Higher quality = higher value multiplier #
type Quality =
+ Bronze      # Common harvest, basic value #
+ Silver      # Good quality, moderate bonus #
+ Gold        # Excellent harvest, high value #
+ Starlight   # Legendary, blessed by the moon #
in

# Crops that grow under the night sky #
# Each crop has a base value determined by cropValue #
type Crop =
+ Moonmelon   # Glows faintly, sweet taste #
+ Starfruit   # Shaped like stars, tangy #
+ Nightshade  # Purple bloom, magical properties #
+ Glowpumpkin # Orange and luminescent #
+ Duskwheat   # Golden stalks, hearty grain #
in

# A single harvest from the garden #
# Combines crop type, quality level, and quantity harvested #
type Harvest = (
crop = Crop,
quality = Quality,
quantity = Int
) in

# The harvest ledger tracks all harvests and bonuses #
# harvests: list of all recorded harvests (newest first) #
# totalValue: cumulative value of all harvests plus claimed bonuses #
# streakBonus: current unclaimed streak bonus #
# lastQuality: quality of the most recent harvest (for streak tracking) #
type Model = (
harvests = [Harvest],
totalValue = Int,
streakBonus = Int,
lastQuality = Quality
) in

# Actions the farmer can take #
type Action =
+ RecordHarvest(Harvest)  # Log a new harvest #
+ ClaimBonus              # Collect accumulated streak bonus #
+ CloseDay                # End the harvest day, reset streaks #
in

# ===== VALUE CALCULATIONS ===== #

let cropValue : Crop -> Int =
fun c ->
case c
| Moonmelon => 15
| Starfruit => 20
| Nightshade => 20
| Glowpumpkin => 12
| Duskwheat => 10
end
in

let qualityMultiplier : Quality -> Int =
fun q ->
case q
| Bronze => 1
| Silver => 2
| Gold => 3
| Starlight => 5
end
in

# Calculate the value of a single harvest #
# Formula: baseValue * qualityMultiplier * quantity #
let harvestValue : Harvest -> Int =
fun h ->
cropValue(h.crop) * qualityMultiplier(h.quality) * h.quantity
in

# ===== LEDGER STATE ===== #

# Initial empty ledger #
# Start of a new harvest day with no recorded harvests #
let initModel : Model = (
harvests = [],
totalValue = 0,
streakBonus = 0,
lastQuality = Bronze
) in

# ===== CORE LOGIC ===== #

# Process a harvest action and update the ledger #
# This function handles streak detection and bonus calculation #
# A streak continues when consecutive harvests have the same quality #
let processHarvest : (Model, Harvest) -> Model =
fun (ledger, h) ->
# Calculate the base value of this harvest #
let value = harvestValue(h) in
# Check if this is the first harvest (no streak possible) #
let isFirst = length(ledger.harvests) == 0 in
# Prepare to update the lastQuality for next comparison #
let newLast = h.quality in
# Determine if the streak continues #
# Streak continues if not first AND current quality matches previous #
let continues = !isFirst && h.quality == newLast in
# Calculate new streak bonus #
# If streak continues, add 5 to existing bonus #
# If streak breaks, reset to 0 #
let newStreak =
if continues
then ledger.streakBonus + 5
else 0
in
# Return updated ledger #
(
harvests = h :: ledger.harvests,
totalValue = ledger.totalValue + value + newStreak,
streakBonus = newStreak,
lastQuality = newLast
)
in

# Claim the streak bonus and reset it #
# Adds current streak bonus to total, then zeroes streak #
let claimBonus : Model -> Model =
fun ledger ->
(
harvests = ledger.harvests,
totalValue = ledger.totalValue + ledger.streakBonus,
streakBonus = 0,
lastQuality = ledger.lastQuality
)
in

# Close the harvest day - reset streak tracking #
# Preserves harvests and total, resets streak state #
let closeDay : Model -> Model =
fun ledger ->
(
harvests = ledger.harvests,
totalValue = ledger.totalValue,
streakBonus = 0,
lastQuality = Bronze
)
in

# ===== ACTION DISPATCH ===== #

# Main update function - dispatch actions #
# Routes each action type to its handler #
let update : (Model, Action) -> Model =
fun (ledger, action) ->
case action
| RecordHarvest(h) => processHarvest(ledger, h)
| ClaimBonus => claimBonus(ledger)
| CloseDay => closeDay(ledger)
end
in

# Run multiple actions in sequence #
# Folds actions left-to-right, threading the ledger through #
let run : (Model, [Action]) -> Model =
fun (ledger, actions) ->
fold_left(actions, fun (l, a) -> update(l, a), ledger)
in

# ===== TESTS ===== #

# Basic harvest recording #
hint "recording harvest adds to total value"
test
let h = (crop = Moonmelon, quality = Bronze, quantity = 2) in
let ledger = update(initModel, RecordHarvest(h)) in
ledger.totalValue == 30
end;

hint "harvest is added to harvests list"
test
let h = (crop = Starfruit, quality = Silver, quantity = 1) in
let ledger = update(initModel, RecordHarvest(h)) in
length(ledger.harvests) == 1
end;

